# Find the smallest number that is the sum of two cubes in two different ways
# We'll check all combinations up to a reasonable limit

def find_taxicab():
    sums_dict = {}  # Map from sum to list of (a, b) pairs

    # Check all pairs (a, b) where a < b
    for a in range(1, 200):
        for b in range(a + 1, 200):
            cube_sum = a**3 + b**3

            if cube_sum not in sums_dict:
                sums_dict[cube_sum] = []
            sums_dict[cube_sum].append((a, b))

    # Find the smallest sum with at least 2 different representations
    for sum_val in sorted(sums_dict.keys()):
        if len(sums_dict[sum_val]) >= 2:
            print(f"Found: {sum_val}")
            for a, b in sums_dict[sum_val]:
                print(f"  {sum_val} = {a}³ + {b}³ = {a**3} + {b**3}")
            return sum_val

result = find_taxicab()
print(f"\nAnswer: {result}")
EOF
